#include <stdio.h>
#include <string.h>

static const unsigned char table[64] = {
    0x2b, 0x07, 0x33, 0x19, 0x3e, 0x0d, 0x21, 0x14, 0x05, 0x38, 0x11, 0x2e, 0x0a, 0x3c, 0x27, 0x01,
    0x1f, 0x35, 0x09, 0x26, 0x13, 0x3a, 0x02, 0x2d, 0x17, 0x30, 0x0f, 0x22, 0x3f, 0x1b, 0x08, 0x29,
    0x36, 0x04, 0x1d, 0x31, 0x0c, 0x28, 0x3b, 0x16, 0x23, 0x0e, 0x34, 0x1a, 0x2f, 0x06, 0x3d, 0x12,
    0x03, 0x2a, 0x18, 0x37, 0x0b, 0x24, 0x10, 0x39, 0x1e, 0x2c, 0x00, 0x32, 0x15, 0x20, 0x1c, 0x25,
};
static const unsigned char expected[] = {0x0a, 0x2a, 0x18, 0x3d, 0x2c, 0x24, 0x16, 0x23};

int main(int argc, char **argv) {
    if (argc != 2 || strlen(argv[1]) != sizeof expected) {
        puts("Invalid");
        return 1;
    }
    for (size_t i = 0; i < sizeof expected; i++) {
        unsigned char c = (unsigned char)argv[1][i];
        if (table[(c + i) & 0x3f] != expected[i]) {
            puts("Invalid");
            return 1;
        }
    }
    puts("Valid");
    return 0;
}
